// ============================================================
// ⚙️ CONFIGURATION GLOBALE
// Modifiez uniquement ce bloc
// ============================================================
const CONFIG = {
  // --- Apify ---
  apifyToken: "apify_api_VOTRE_TOKEN",       // ← Votre token Apify

  // --- Niches à scanner (hashtags Instagram) ---
  hashtags: [
    "coiffureAbidjan",
    "boutiqueAbidjan",
    "restaurantAbidjan",
    "beauteAbidjan"
  ],
  maxPostsPerHashtag: 20,   // Nombre de posts à scraper par hashtag

  // --- Evolution API ---
  evolutionApiUrl: "https://VOTRE_URL.railway.app",  // ← URL Railway/VPS
  evolutionApiKey: "VOTRE_CLE_SECRETE",              // ← Clé définie à l'install
  evolutionInstance: "prospect-bot",                 // ← Nom de l'instance créée
  whatsappTestMessage: "Bonjour 👋",
  whatsappTimeoutMs: 15000,

  // --- Général ---
  maxAccountsPerRun: 20,
  runStartedAt: new Date().toISOString()
};

console.log(`[CONFIG] Run démarré | Hashtags: ${CONFIG.hashtags.join(', ')} | Max: ${CONFIG.maxAccountsPerRun}`);
return [{ json: CONFIG }];

// Génère un item par hashtag pour paralléliser
const config = $input.item.json;
return config.hashtags.map(tag => ({
  json: { ...config, currentHashtag: tag }
}));

// ============================================================
// EXTRACTION ET NORMALISATION DES PROFILS APIFY
// ============================================================
const items = $input.all();
const config = $('⚙️ Configuration').item.json;
const profiles = [];

for (const item of items) {
  const posts = Array.isArray(item.json) ? item.json : [item.json];

  for (const post of posts) {
    if (!post || !post.ownerUsername) continue;

    // Apify retourne ces champs pour chaque post
    profiles.push({
      json: {
        username: post.ownerUsername || post.username || "",
        bio: post.ownerBiography || post.biography || "",
        website: post.ownerExternalUrl || post.website || "",
        followersCount: post.ownerFollowersCount || 0,
        fullName: post.ownerFullName || "",
        isVerified: post.ownerIsVerified || false,
        instagramUrl: `https://instagram.com/${post.ownerUsername}`,
        scrapedHashtag: post.hashtags?.[0] || config.currentHashtag || "",
        postLikes: post.likesCount || 0,
        postUrl: post.url || "",
        scrapedAt: new Date().toISOString(),
        // Config transmise
        evolutionApiUrl: config.evolutionApiUrl,
        evolutionApiKey: config.evolutionApiKey,
        evolutionInstance: config.evolutionInstance,
        whatsappTestMessage: config.whatsappTestMessage,
        maxAccountsPerRun: config.maxAccountsPerRun
      }
    });
  }
}

// Dédoublonnage par username
const seen = new Set();
const unique = profiles.filter(p => {
  if (seen.has(p.json.username)) return false;
  seen.add(p.json.username);
  return true;
});

// Limite par run
const limited = unique.slice(0, config.maxAccountsPerRun);
console.log(`[APIFY] Posts récupérés: ${profiles.length} | Uniques: ${unique.length} | Après limite: ${limited.length}`);

if (limited.length === 0) {
  return [{ json: { _empty: true, message: "Aucun profil récupéré par Apify" } }];
}

return limited;

// ============================================================
// FILTRAGE : Détection liens WhatsApp dans la bio/website
// ============================================================
const items = $input.all();
const withWA = [];

const waPatterns = [
  { regex: /wa\.me\/(\d+)/i, type: "wa.me" },
  { regex: /wa\.link\/([\w-]+)/i, type: "wa.link" },
  { regex: /whatsapp/i, type: "mention" },
  { regex: /watsap/i, type: "mention" }
];

for (const item of items) {
  if (item.json._empty) continue;
  const p = item.json;
  const text = `${p.bio} ${p.website}`.toLowerCase();

  let waLink = null;
  let waPhone = null;
  let waType = null;

  for (const pattern of waPatterns) {
    const match = text.match(pattern.regex);
    if (match) {
      waType = pattern.type;
      if (pattern.type === "wa.me") {
        waPhone = match[1];
        waLink = `https://wa.me/${waPhone}`;
      } else if (pattern.type === "wa.link") {
        waLink = `https://wa.link/${match[1]}`;
      } else {
        waLink = p.website || "mention dans bio";
      }
      break;
    }
  }

  if (waLink) {
    withWA.push({
      json: {
        ...p,
        whatsappLink: waLink,
        whatsappPhone: waPhone,
        whatsappType: waType
      }
    });
    console.log(`[FILTRAGE ✅] @${p.username} → ${waType} → ${waLink}`);
  } else {
    console.log(`[FILTRAGE ❌] @${p.username} → Pas de WhatsApp détecté`);
  }
}

console.log(`[FILTRAGE] Total avec WhatsApp: ${withWA.length}`);

if (withWA.length === 0) {
  return [{ json: { _empty: true, message: "Aucun compte avec WhatsApp dans ce run" } }];
}

return withWA;

// Comptes sans numéro extractible → statut direct
const p = $input.item.json;
console.log(`[NO PHONE] @${p.username} → wa.link ou mention, pas de numéro direct`);
return [{
  json: {
    ...p,
    whatsappTestStatus: "absente",
    whatsappTestNote: "Lien wa.link ou mention — numéro non extractible",
    whatsappResponse: null
  }
}];

// ============================================================
// ANALYSE RÉPONSE EVOLUTION API
// ============================================================
const sendResult = $input.item.json;
const prevData = $('🔎 Filtrage WhatsApp').item.json;

let status = "absente";
let note = "";

try {
  const statusCode = sendResult.statusCode || 0;
  const body = sendResult.body || sendResult;

  if (statusCode === 200 || statusCode === 201 || body?.key?.id) {
    // Message envoyé avec succès
    // Evolution API ne retourne pas la réponse du destinataire ici
    // Pour analyser la réponse, il faudrait configurer un webhook
    // On marque comme envoyé et on analyse via IA
    status = "message_envoye";
    note = `MessageId: ${body?.key?.id || 'ok'}`;
    console.log(`[EVO ✅] @${prevData.username} → Message envoyé`);
  } else {
    status = "absente";
    note = `Erreur envoi: ${statusCode} — ${JSON.stringify(body).substring(0, 100)}`;
    console.log(`[EVO ❌] @${prevData.username} → ${note}`);
  }
} catch (e) {
  status = "absente";
  note = `Exception: ${e.message}`;
}

return [{
  json: {
    ...prevData,
    whatsappTestStatus: status,
    whatsappTestNote: note,
    whatsappResponse: null,
    testedAt: new Date().toISOString()
  }
}];

