const item = $input.item.json;
const prev = $('🔀 Merge Branches').item.json;

let ai = { automatisation_existante: false, efficace_ventes: false, opportunite: "non", raison: "Analyse indisponible", score_prospect: 0 };
try {
  const raw = item.choices?.[0]?.message?.content || "{}";
  ai = JSON.parse(raw.replace(/```json|```/g, "").trim());
} catch(e) { console.error("[AI PARSE]", e.message); }

return [{ json: { ...prev, ai, opportunite: ai.opportunite, raison: ai.raison, scoreProspect: ai.score_prospect } }];

